function sourceJson(value) {
  if (typeof value === "string") return JSON.parse(value);
  return value || {};
}

function sourceStatus(response) {
  var status = response && (response.statusCode || response.status);
  status = Number(status);
  return isFinite(status) && status > 0 ? status : 0;
}

function sourceStrip(value) {
  return sourceText(value)
    .replace(/<script[\s\S]*?<\/script>/gi, " ")
    .replace(/<style[\s\S]*?<\/style>/gi, " ")
    .replace(/<[^>]+>/g, " ")
    .replace(/&nbsp;|&#160;/gi, " ")
    .replace(/&amp;/gi, "&")
    .replace(/&lt;/gi, "<")
    .replace(/&gt;/gi, ">")
    .replace(/&quot;/gi, "\"")
    .replace(/&#39;|&apos;/gi, "'")
    .replace(/\s+/g, " ")
    .trim();
}

function sourceUrl(value) {
  var url = sourceText(value).trim();
  return url.indexOf("//") === 0 ? "https:" + url : url;
}

function sourcePage(value) {
  var number = Math.floor(Number(value));
  return isFinite(number) && number > 0 ? number : 1;
}

function sourceApiUrl(params) {
  var pairs = [];
  Object.keys(params || {}).forEach(function (key) {
    var value = params[key];
    if (value === undefined || value === null || value === "") return;
    pairs.push(encodeURIComponent(key) + "=" + encodeURIComponent(String(value)));
  });
  return SOURCE_CONFIG.api + (SOURCE_CONFIG.api.indexOf("?") >= 0 ? "&" : "?") + pairs.join("&");
}

function sourceHeaders() {
  return {
    "User-Agent": "Mozilla/5.0 (Rex ForwardWidget; " + SOURCE_CONFIG.slug + "/" + SOURCE_CONFIG.version + ")",
    Accept: "application/json, text/plain, */*",
    Referer: SOURCE_CONFIG.site
  };
}

async function sourceGet(params) {
  var response;
  try {
    response = await Widget.http.get(sourceApiUrl(params), { headers: sourceHeaders() });
  } catch (error) {
    throw new Error("[" + SOURCE_CONFIG.slug.toUpperCase() + "-NET] 接口请求失败：" + (error && error.message ? error.message : error));
  }
  var status = sourceStatus(response);
  if (status >= 400) throw new Error("[" + SOURCE_CONFIG.slug.toUpperCase() + "-HTTP] 接口返回 HTTP " + status);
  var result;
  try {
    result = sourceJson(response && response.data);
  } catch (error) {
    throw new Error("[" + SOURCE_CONFIG.slug.toUpperCase() + "-JSON] 接口没有返回有效 JSON");
  }
  if (Number(result.code) !== 1 && !Array.isArray(result.list)) {
    throw new Error("[" + SOURCE_CONFIG.slug.toUpperCase() + "-API] " + (sourceStrip(result.msg) || "接口返回异常"));
  }
  return result;
}

function sourceBlocked(item) {
  var haystack = [item && item.type_name, item && item.vod_name, item && item.vod_sub,
    item && item.vod_class, item && item.vod_tag, item && item.vod_remarks].map(sourceText).join(" ").toLowerCase();
  for (var i = 0; i < SOURCE_BLOCKED_WORDS.length; i += 1) {
    if (haystack.indexOf(SOURCE_BLOCKED_WORDS[i].toLowerCase()) >= 0) return true;
  }
  return false;
}

function sourceMediaType(item) {
  var value = sourceText((item && item.type_name) || "") + " " + sourceText((item && item.vod_class) || "");
  return /剧|连续|电视|动漫|动画|综艺|短剧/i.test(value) ? "tv" : "movie";
}

function sourceLink(id) {
  return "rexvod://" + SOURCE_CONFIG.slug + "/" + encodeURIComponent(sourceText(id));
}

function sourceId(link) {
  var value = sourceText(link).trim();
  var pattern = new RegExp("^rexvod://" + SOURCE_CONFIG.slug + "/([^/?#]+)", "i");
  var match = value.match(pattern);
  if (match) return decodeURIComponent(match[1]);
  if (/^\d+$/.test(value)) return value;
  match = value.match(/[?&](?:id|ids)=(\d+)/i);
  return match ? match[1] : "";
}

function sourceGenres(item) {
  var result = [];
  var seen = {};
  [item && item.type_name].concat(sourceText(item && item.vod_class).split(/[,，/]/)).forEach(function (name) {
    name = sourceStrip(name);
    if (!name || seen[name]) return;
    seen[name] = true;
    result.push({ id: sourceText(item && item.type_id) || name, title: name });
  });
  return result;
}

function sourceDescription(item, includeContent) {
  var lines = [];
  var meta = [sourceStrip(item && item.vod_year), sourceStrip(item && item.vod_area), sourceStrip(item && item.vod_lang)].filter(Boolean);
  if (meta.length) lines.push(meta.join(" · "));
  var remarks = sourceStrip(item && item.vod_remarks);
  if (remarks) lines.push("状态：" + remarks);
  var director = sourceStrip(item && item.vod_director);
  var actor = sourceStrip(item && item.vod_actor);
  if (director) lines.push("导演：" + director);
  if (actor) lines.push("主演：" + actor);
  if (includeContent) {
    var content = sourceStrip((item && (item.vod_content || item.vod_blurb)) || "");
    if (content) lines.push("\n简介：\n" + content);
  }
  return lines.join("\n");
}

function sourceListItem(item) {
  if (!item || sourceBlocked(item)) return null;
  var id = sourceText(item.vod_id).trim();
  if (!id) return null;
  var cover = sourceUrl(item.vod_pic);
  return {
    id: sourceLink(id), type: "url", title: sourceStrip(item.vod_name) || (SOURCE_CONFIG.shortName + "影片 " + id),
    description: sourceDescription(item, false), coverUrl: cover, posterPath: cover, detailPoster: cover,
    releaseDate: sourceStrip(item.vod_pubdate || item.vod_year), mediaType: sourceMediaType(item),
    genreTitle: sourceStrip(item.type_name || item.vod_class), genreItems: sourceGenres(item),
    rating: sourceStrip(item.vod_score), link: sourceLink(id), playerType: "app"
  };
}

function sourceMapList(list) {
  return (Array.isArray(list) ? list : []).map(sourceListItem).filter(Boolean);
}

function sourceM3u8(url) {
  var clean = sourceText(url).trim();
  return /^https?:\/\//i.test(clean) && /\.m3u8(?:[?#]|$)/i.test(clean);
}

function sourcePlayLines(item) {
  var sources = sourceText(item && item.vod_play_from).split("$$$");
  var groups = sourceText(item && item.vod_play_url).split("$$$");
  var result = [];
  groups.forEach(function (group, groupIndex) {
    var source = sourceText(sources[groupIndex] || ("线路" + (groupIndex + 1))).trim();
    var entries = sourceText(group).split("#");
    var parsed = [];
    entries.forEach(function (entry, entryIndex) {
      var raw = sourceText(entry).trim();
      if (!raw) return;
      var separator = raw.indexOf("$");
      var title = separator >= 0 ? raw.slice(0, separator) : ("第" + (entryIndex + 1) + "集");
      var url = sourceUrl(separator >= 0 ? raw.slice(separator + 1) : raw);
      if (!sourceM3u8(url)) return;
      parsed.push({ source: source || SOURCE_CONFIG.shortName, title: sourceStrip(title) || ("第" + (entryIndex + 1) + "集"), url: url, index: entryIndex + 1 });
    });
    if (/m3u8/i.test(source) || parsed.length) result = result.concat(parsed);
  });
  return result;
}

function sourceEpisodes(item, lines) {
  var cover = sourceUrl(item && item.vod_pic);
  var title = sourceStrip(item && item.vod_name);
  return lines.map(function (line, index) {
    return { id: line.url, type: "url", title: line.title, description: title + "\n来源：" + SOURCE_CONFIG.name,
      coverUrl: cover, posterPath: cover, mediaType: sourceMediaType(item), episode: line.index || index + 1,
      videoUrl: line.url, link: sourceLink(item.vod_id), playerType: "app" };
  });
}

function sourceDetailItem(item) {
  var base = sourceListItem(item);
  if (!base) return null;
  var lines = sourcePlayLines(item);
  base.description = sourceDescription(item, true);
  base.backdropPath = base.coverUrl;
  base.backdropPaths = base.coverUrl ? [base.coverUrl] : [];
  base.episodeItems = sourceEpisodes(item, lines);
  if (base.episodeItems.length) base.videoUrl = base.episodeItems[0].videoUrl;
  if (!base.episodeItems.length) base.description += (base.description ? "\n\n" : "") + "当前没有可直接播放的 M3U8 地址。";
  return base;
}

function sourceUnique(items) {
  var seen = {};
  return items.filter(function (item) {
    var key = sourceText(item && (item.id || item.link));
    if (!key || seen[key]) return false;
    seen[key] = true;
    return true;
  });
}

async function loadSourceHome(params) {
  var result = await sourceGet({ ac: "list", pg: sourcePage(params && params.page) });
  return sourceMapList(result.list);
}

async function loadSourceChannel(params, channel) {
  params = params || {};
  var selected = sourceText(params.genreId || params.category || "all");
  var categories = (SOURCE_CONFIG.categories && SOURCE_CONFIG.categories[channel]) || [];
  var ids = selected !== "all" ? [selected] : categories.map(function (row) { return sourceText(row.value); }).slice(0, 8);
  if (!ids.length) return [];
  var page = sourcePage(params.page);
  var responses = await Promise.all(ids.map(function (id) {
    return sourceGet({ ac: "list", t: id, pg: page }).catch(function () { return { list: [] }; });
  }));
  var items = [];
  responses.forEach(function (response) { items = items.concat(sourceMapList(response.list)); });
  return sourceUnique(items).slice(0, 60);
}

function loadSourceMovies(params) { return loadSourceChannel(params, "movie"); }
function loadSourceSeries(params) { return loadSourceChannel(params, "tv"); }
function loadSourceVariety(params) { return loadSourceChannel(params, "variety"); }
function loadSourceAnime(params) { return loadSourceChannel(params, "anime"); }
function loadSourceShort(params) { return loadSourceChannel(params, "short"); }

async function searchSource(params) {
  params = params || {};
  var keyword = sourceStrip(params.keyword || params.wd || params.query);
  if (!keyword) return [];
  var result = await sourceGet({ ac: "detail", wd: keyword, pg: sourcePage(params.page) });
  return sourceMapList(result.list);
}

async function loadDetail(link) {
  var id = sourceId(link);
  if (!id) return null;
  var result = await sourceGet({ ac: "detail", ids: id });
  var list = Array.isArray(result.list) ? result.list : [];
  for (var i = 0; i < list.length; i += 1) {
    if (sourceText(list[i] && list[i].vod_id) === id) return sourceDetailItem(list[i]);
  }
  return list.length ? sourceDetailItem(list[0]) : null;
}

function sourceNormalize(value) {
  return sourceStrip(value).toLowerCase().replace(/[（(][^）)]*[）)]/g, "").replace(/[\s·•:：,，.。!！?？'\"“”‘’\-_/\\]/g, "");
}

function sourceSeason(value) {
  var text = sourceStrip(value);
  var match = text.match(/第\s*([0-9一二三四五六七八九十]+)\s*季/i);
  return match ? match[1] : "";
}

function sourcePick(list, keyword, params) {
  var wanted = sourceNormalize(keyword);
  var requestedYear = sourceText(params && params.year).trim();
  var requestedType = sourceText(params && params.type).toLowerCase();
  var requestedSeason = sourceSeason(keyword) || sourceText(params && params.season).trim();
  var candidates = (Array.isArray(list) ? list : []).filter(function (item) {
    if (!item || sourceBlocked(item) || !sourcePlayLines(item).length) return false;
    if (sourceNormalize(item.vod_name) !== wanted) return false;
    if (requestedYear && sourceText(item.vod_year).trim() && sourceText(item.vod_year).trim() !== requestedYear) return false;
    if ((requestedType === "tv" || requestedType === "movie") && sourceMediaType(item) !== requestedType) return false;
    var itemSeason = sourceSeason(item.vod_name) || sourceSeason(item.vod_remarks);
    if (requestedSeason && itemSeason && itemSeason !== requestedSeason) return false;
    return true;
  });
  return candidates.length === 1 ? candidates[0] : null;
}

function sourceVideoResource(line) {
  return { name: line.title || (SOURCE_CONFIG.shortName + " M3U8"), description: "来源：" + SOURCE_CONFIG.name,
    url: line.url, playerType: "app" };
}

async function loadResource(params) {
  params = params || {};
  var direct = [params.videoUrl, params.url, params.id];
  for (var i = 0; i < direct.length; i += 1) {
    var directUrl = sourceUrl(direct[i]);
    if (sourceM3u8(directUrl)) return [sourceVideoResource({ title: sourceStrip(params.episodeName || params.title), url: directUrl })];
  }
  var id = sourceId(params.link || params.id);
  var result;
  var detail;
  if (id) {
    result = await sourceGet({ ac: "detail", ids: id });
    detail = Array.isArray(result.list) && result.list.length ? result.list[0] : null;
  } else {
    var keyword = sourceStrip(params.seriesName || params.title || params.name);
    if (!keyword) return [];
    result = await sourceGet({ ac: "detail", wd: keyword });
    detail = sourcePick(result.list, keyword, params);
  }
  if (!detail) return [];
  var lines = sourcePlayLines(detail);
  if (!lines.length) return [];
  var episodeName = sourceStrip(params.episodeName);
  if (episodeName) {
    for (var lineIndex = 0; lineIndex < lines.length; lineIndex += 1) {
      if (sourceStrip(lines[lineIndex].title) === episodeName) return [sourceVideoResource(lines[lineIndex])];
    }
    return [];
  }
  var episode = Math.floor(Number(params.episode));
  if (isFinite(episode) && episode > 0) {
    var hasNumberedTitles = false;
    for (var numberedIndex = 0; numberedIndex < lines.length; numberedIndex += 1) {
      var number = sourceEpisodeNumber(lines[numberedIndex].title);
      if (number > 0) hasNumberedTitles = true;
      if (number === episode) return [sourceVideoResource(lines[numberedIndex])];
    }
    return hasNumberedTitles || !lines[episode - 1] ? [] : [sourceVideoResource(lines[episode - 1])];
  }
  return [sourceVideoResource(lines[0])];
}
function sourceEpisodeNumber(value) {
  var title = sourceStrip(value);
  var match = title.match(/第\s*0*(\d+)\s*(?:集|话|期|回)/i) || title.match(/(?:EP|E)\s*0*(\d+)$/i);
  if (match) return Number(match[1]);
  match = title.match(/^0*(\d{1,4})$/);
  return match ? Number(match[1]) : 0;
}
